import jsonimport pygame# for autotiling, we want rules specifying which tiles to use depending on which neighboursAUTOTILE_MAP = {    tuple(sorted([(1, 0),  (0, 1)])): 0, # place topleft if there is tile to right and tile below    tuple(sorted([(1, 0),  (0, 1), (-1, 0)])): 1, # if tile to right, below and left    tuple(sorted([(-1, 0),  (0, 1)])): 2,    tuple(sorted([(-1, 0),  (0, -1), (0, 1)])): 3,    tuple(sorted([(-1, 0),  (0, -1)])): 4,    tuple(sorted([(-1, 0),  (0, -1), (1, 0)])): 5,    tuple(sorted([(1, 0),  (0, -1)])): 6,    tuple(sorted([(1, 0),  (0, -1), (0, 1)])): 7,    tuple(sorted([(1, 0),  (-1, 0), (0, 1), (0, -1)])): 8    }NEIGHBOUR_OFFSETS = [(-1, 0), (-1, -1), (0, -1), (1, -1), (1, 0), (0, 0), (-1, 1), (0, 1), (1, 1)]PHYSICS_TILES = {'grass', 'mud'} # sets are faster than lists for lookupsAUTOTILE_TYPES = {'grass', 'mud'}class Tilemap():    def __init__(self, game, tile_size=16):        self.game = game        self.tile_size = tile_size        self.tilemap = {}        self.offgrid_tiles = []                # # example tile map generation        # # tile is represented as a dict with multiple attributes        # for i in range(20):        #     self.tilemap[str(10 + i) + ';10'] = {'type': 'grass', # tile of type grass        #                                          'variant': 2, # type of grass tile        #                                          'pos': (10 + i, 10)} # tile position        #     self.tilemap['10;' + str(1 + i)] = {'type': 'mud',         #                                         'variant': 1,        #                                         'pos': (10, 1 + i)}            def extract(self, id_pairs, keep=False):        matches = []        for tile in self.offgrid_tiles.copy():            if (tile['type'], tile['variant']) in id_pairs:                matches.append(tile.copy())                if not keep:                    self.offgrid_tiles.remove(tile)                for loc in self.tilemap:            tile = self.tilemap[loc]            if (tile['type'], tile['variant']) in id_pairs:                matches.append(tile.copy())                # change pos for tile to be in pixels                matches[-1]['pos'] = matches[-1]['pos'].copy()                matches[-1]['pos'][0] *= self.tile_size                matches[-1]['pos'][1] *= self.tile_size                if not keep:                    del self.tilemap[loc]        return matches                            def tiles_around(self, pos):        """ for efficiency only check tiles around the player to calculate            collisions """        # convert grid to pixel position        tile_loc = (int(pos[0] // self.tile_size), # x-axis pos                    int(pos[1] // self.tile_size)) # y-axis pos        tiles = []        for offset in NEIGHBOUR_OFFSETS:            check_loc = (str(tile_loc[0] + offset[0]) + ';' +                         str(tile_loc[1] + offset[1]))            if check_loc in self.tilemap:                tiles.append(self.tilemap[check_loc])        return tiles        def save(self, path):        f = open(path, 'w')        json.dump({'tilemap': self.tilemap,                   'tile_size': self.tile_size,                   'offgrid': self.offgrid_tiles}, f)        f.close()        def load(self, path):        f = open(path, 'r')        map_data = json.load(f)        f.close()                self.tilemap = map_data['tilemap']        self.tile_size = map_data['tile_size']        self.offgrid_tiles = map_data['offgrid']        def physics_rects_around(self, pos):        rects = []        for tile in self.tiles_around(pos):            if tile['type'] in PHYSICS_TILES: # check if can collide with this tile                rects.append(pygame.Rect(tile['pos'][0] * self.tile_size,                                         tile['pos'][1] * self.tile_size,                                         self.tile_size,                                          self.tile_size))        return rects        def autotile(self):        for loc in self.tilemap:            tile = self.tilemap[loc]            neighbours = set()            for shift in [(1, 0), (-1, 0), (0, -1), (0, 1)]:                check_loc = str(tile['pos'][0] + shift[0]) + ';' + str(tile['pos'][1] + shift[1])                if check_loc in self.tilemap:                    if self.tilemap[check_loc]['type'] == tile['type']:                        # make sure neighbouring tile is the same type as itself                        neighbours.add(shift)            neighbours = tuple(sorted(neighbours))            if (tile['type'] in AUTOTILE_TYPES) and (neighbours in AUTOTILE_MAP):                tile['variant'] = AUTOTILE_MAP[neighbours]                def render(self, surf, offset=(0, 0)):        for tile in self.offgrid_tiles:            surf.blit(self.game.assets[tile['type']][tile['variant']],                      (tile['pos'][0] - offset[0], tile['pos'][1] - offset[1]))        for x in range(offset[0] // self.tile_size, # top left tile x-pos                       (offset[0] + surf.get_width()) // self.tile_size + 1):            for y in range(offset[1] // self.tile_size, # top left tile x-pos                           (offset[1] + surf.get_height()) // self.tile_size + 1):                loc = str(x) + ';' + str(y)                if loc in self.tilemap:                    tile = self.tilemap[loc]                    surf.blit(self.game.assets[tile['type']][tile['variant']],                               (tile['pos'][0] * self.tile_size - offset[0],                                tile['pos'][1] * self.tile_size - offset[1]))    